nebula.init_snippet_three:
// Inject as a fullscreen plane behind the scene
const nebulaMat = new THREE.ShaderMaterial({
  uniforms: { u_time: { value: 0 }, u_resolution: { value: new THREE.Vector2(innerWidth, innerHeight) } },
  vertexShader: 'void main(){gl_Position=vec4(position,1.0);}',
  fragmentShader: NEBULA_FRAG // paste fragment_shader here
});
const nebulaQuad = new THREE.Mesh(new THREE.PlaneGeometry(2,2), nebulaMat);
nebulaQuad.frustumCulled = false;
scene.add(nebulaQuad);

starfield.init_snippet_three:
const starsGeo = new THREE.BufferGeometry();
const N = 3000;
const pos = new Float32Array(N*3);
for(let i=0;i<N;i++){pos[i*3]=(Math.random()-0.5)*2000;pos[i*3+1]=(Math.random()-0.5)*2000;pos[i*3+2]=(Math.random()-0.5)*2000;}
starsGeo.setAttribute('position', new THREE.BufferAttribute(pos, 3));
const starsMat = new THREE.PointsMaterial({ color:0xffffff, size:1.5, transparent:true, opacity:0.85 });
const stars = new THREE.Points(starsGeo, starsMat);
scene.add(stars);
// in animate(): stars.rotation.y += 0.0005; stars.rotation.x += 0.0002;

