glitch.css_snippet:
.glitch { position: relative; }
.glitch::before, .glitch::after { content: attr(data-text); position: absolute; top:0; left:0; width:100%; height:100%; }
.glitch::before { animation: glitchTop 1s linear infinite; clip-path: polygon(0 0, 100% 0, 100% 33%, 0 33%); transform: translate(-2px, -2px); color: #ff00ff; }
.glitch::after { animation: glitchBot 1.5s linear infinite; clip-path: polygon(0 67%, 100% 67%, 100% 100%, 0 100%); transform: translate(2px, 2px); color: #00ffff; }
@keyframes glitchTop { 2%, 64% { transform: translate(2px, -2px); } 4%, 60% { transform: translate(-2px, 2px); } 62% { transform: translate(13px, -1px) skew(-13deg); } }
@keyframes glitchBot { 10%, 50% { transform: translate(-2px, 0); } 14%, 56% { transform: translate(2px, 0); } 50% { transform: translate(-22px, 5px) skew(21deg); } }

