chromatic_aberration.css_snippet:
.chromatic { position: relative; }
.chromatic::before, .chromatic::after { content: ''; position: absolute; inset: 0; mix-blend-mode: screen; pointer-events: none; }
.chromatic::before { background: inherit; transform: translate(-2px, 0); filter: blur(0.5px) drop-shadow(0 0 1px #ff0000); opacity: 0.5; }
.chromatic::after { background: inherit; transform: translate(2px, 0); filter: blur(0.5px) drop-shadow(0 0 1px #00ffff); opacity: 0.5; }

neon_glow.css_snippet:
.neon-pink { color:#fff; text-shadow:0 0 5px #fff, 0 0 10px #ff006e, 0 0 20px #ff006e, 0 0 40px #ff006e, 0 0 80px #ff006e; }
.neon-cyan { color:#fff; text-shadow:0 0 5px #fff, 0 0 10px #00f5ff, 0 0 20px #00f5ff, 0 0 40px #00f5ff, 0 0 80px #00f5ff; }
.neon-border { border:2px solid #00f5ff; box-shadow:0 0 10px #00f5ff, inset 0 0 10px #00f5ff; }
.neon-pulse { animation: neonPulse 1.5s ease-in-out infinite alternate; }
@keyframes neonPulse { from { text-shadow:0 0 5px #fff, 0 0 10px #ff006e; } to { text-shadow:0 0 8px #fff, 0 0 20px #ff006e, 0 0 30px #ff006e, 0 0 50px #ff006e; } }

