audio_visualizer_simple.css_snippet:
.bars { display:flex; gap:3px; align-items:flex-end; height:30px; }
.bars span { width:4px; background:#ff006e; animation: barJump 1s ease-in-out infinite; }
.bars span:nth-child(1){animation-delay:-0.3s} .bars span:nth-child(2){animation-delay:-0.6s} .bars span:nth-child(3){animation-delay:-0.9s} .bars span:nth-child(4){animation-delay:-0.4s} .bars span:nth-child(5){animation-delay:-0.8s}
@keyframes barJump { 0%,100% { height:10%; } 50% { height:100%; } }
